def print_help() -> None:
    sys.stdout.write(HELP_TEXT)


def die(msg: str, code: int = 1, stream=None) -> int:
    if stream is None:
        stream = sys.stderr
    stream.write(f"tig: {msg}\n")
    try:
        stream.flush()
    except Exception:
        pass
    return code


def run_git(args: List[str], input_text: Optional[str] = None, check: bool = False) -> subprocess.CompletedProcess:
    env = os.environ.copy()
    # Do not force color; Tig strips/parses colors from Git's output.
    env.setdefault("GIT_PAGER", "cat")
    cmd = ["git"] + args
    return subprocess.run(cmd, input=input_text, text=True, stdout=subprocess.PIPE,
                          stderr=subprocess.PIPE, env=env, check=False)


def git_output(args: List[str], default: str = "") -> str:
    try:
        cp = run_git(args)
        if cp.returncode == 0:
            return cp.stdout
        return default
    except (OSError, subprocess.SubprocessError):
        return default


def git_ok(args: List[str]) -> bool:
    try:
        return run_git(args).returncode == 0
    except OSError:
        return False


def apply_chdir_options(argv: List[str]) -> List[str]:
    """Handle the observable Tig-specific '-C <path>' option.

    Only the separated form with a following non-option path is acted upon by
    the reference binary in the observed cases.  Invalid directories are
    reported before help/version is considered.
    """
    out: List[str] = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "-C" and i + 1 < len(argv) and not argv[i + 1].startswith("-"):
            path = argv[i + 1]
            try:
                os.chdir(path)
            except OSError:
                raise RuntimeError(f"Failed to change directory to {path}")
            i += 2
            continue
        out.append(a)
        i += 1
    return out


def first_control_option(argv: List[str]) -> Optional[str]:
    for a in argv:
        if a in ("-v", "--version"):
            return "version"
        if a in ("-h", "--help"):
            return "help"
    return None


def strip_line_number_args(argv: List[str]) -> Tuple[List[str], int]:
    out: List[str] = []
    line = 1
    for a in argv:
        if len(a) > 1 and a[0] == "+" and a[1:].isdigit():
            try:
                line = max(1, int(a[1:]))
            except ValueError:
                line = 1
        else:
            out.append(a)
    return out, line


def valid_revision_spec(spec: str) -> bool:
    if not spec:
        return False
    # Existing pathspecs are accepted as paths rather than revisions.
    if os.path.exists(spec):
        return True
    # Common range/selectors are best validated by rev-list.
    if not shutil.which("git"):
        return False
    try:
        cp = subprocess.run(["git", "rev-list", "--quiet", "-n1", spec, "--"],
                            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                            text=True)
        return cp.returncode == 0
    except OSError:
        return False


def should_report_no_revisions(argv: List[str]) -> bool:
    """Replicate the pre-terminal 'No revisions' checks for obvious bad revs."""
    if not argv:
        return False
    # Subcommand-specific validation observed for `show bad`.
    if argv[0] == "show" and len(argv) > 1:
        a = argv[1]
        if not a.startswith("-") and a != "--" and not valid_revision_spec(a):
            return True
        return False
    if argv[0] in SUBCOMMANDS:
        return False
    # Options are mostly passed through to Git and do not trigger early errors.
    first = argv[0]
    if first == "--":
        return False
    if first.startswith("-"):
        return False
    if first.startswith("+"):
        return not (len(first) > 1 and first[1:].isdigit())
    return not valid_revision_spec(first)


def in_git_repository() -> bool:
    return git_ok(["rev-parse", "--git-dir"])


def git_has_commits(rev_args: List[str]) -> bool:
    args = [a for a in rev_args if not (len(a) > 1 and a[0] == "+" and a[1:].isdigit())]
    if args and args[0] in SUBCOMMANDS:
        args = args[1:]
    # path-only invocations in an unborn repository should still be empty.
    try:
        cp = run_git(["rev-list", "--quiet", "-n1"] + (args if args else ["HEAD"]))
        return cp.returncode == 0
    except Exception:
        return False


def clean_lines(text: str) -> List[str]:
    text = text.replace("\t", "        ")
    return text.splitlines()


def current_branch() -> str:
    b = git_output(["rev-parse", "--abbrev-ref", "HEAD"]).strip()
    return b if b and b != "HEAD" else "HEAD"


def worktree_summary() -> Optional[str]:
    status = git_output(["status", "--porcelain"])  # empty is clean
    if not status:
        return None
    lines = [ln for ln in status.splitlines() if ln]
    if lines and all(ln.startswith("??") for ln in lines):
        return "Untracked changes"
    if any(ln and ln[0] not in (" ", "?") for ln in lines):
        return "Staged changes"
    return "Unstaged changes"


def view_main(args: List[str]) -> Tuple[str, str, List[str], int]:
    rev_args = args[:]
    # If only pathspecs/revs are supplied, pass them straight to git-log.
    pretty = "%ad %an %d %s"
    cmd = ["log", "--date=format:%Y-%m-%d %H:%M %z", f"--pretty=format:{pretty}"] + rev_args
    cp = run_git(cmd)
    lines: List[str] = []
    summary = worktree_summary()
    if summary:
        now = _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%d %H:%M %z")
        lines.append(f"{now} Not Committed Yet o {summary}")
    if cp.returncode == 0 and cp.stdout:
        lines.extend(clean_lines(cp.stdout))
    title = summary or (current_branch() if in_git_repository() else "")
    return "main", title, lines, 0


def view_log(args: List[str]) -> Tuple[str, str, List[str], int]:
    cp = run_git(["log", "--stat", "--decorate=short", "--date=local"] + args)
    lines = clean_lines(cp.stdout) if cp.returncode == 0 else []
    return "log", "", lines, 0


def view_show(args: List[str]) -> Tuple[str, str, List[str], int]:
    cmd = ["show", "--stat", "--patch", "--decorate=short", "--format=fuller"] + args
    cp = run_git(cmd)
    lines = clean_lines(cp.stdout) if cp.returncode == 0 else []
    return "diff", "", lines, 0


def parse_blame_args(args: List[str]) -> Tuple[List[str], Optional[str]]:
    if not args:
        return [], None
    if "--" in args:
        idx = args.index("--")
        before = args[:idx]
        after = args[idx + 1:]
        return before, after[-1] if after else None
    # Last non-option is the path; preceding args are blame/rev options.
    return args[:-1], args[-1]


def view_blame(args: List[str]) -> Tuple[str, str, List[str], int]:
    before, path = parse_blame_args(args)
    if not path:
        return "error", "Invalid number of options to blame", [], 1
    cp = run_git(["blame", "--date=iso", "--"] + [path] if not before else ["blame", "--date=iso"] + before + ["--", path])
    if cp.returncode != 0:
        return "blame", path, [f"No blame exist for {path}"], 1
    return "blame", path, clean_lines(cp.stdout), 0


def view_grep(args: List[str]) -> Tuple[str, str, List[str], int]:
    if not args:
        return "grep", "", ["No matches found"], 0
    cp = run_git(["grep", "-n"] + args)
    if cp.returncode != 0 or not cp.stdout:
        return "grep", "", ["No matches found"], 0
    out: List[str] = []
    for ln in cp.stdout.splitlines():
        # git grep -n: file:line:text, or rev:file:line:text
        parts = ln.split(":", 2)
        if len(parts) == 3:
            out.append(f"{parts[0]}:{parts[1]} {parts[2]}")
        else:
            out.append(ln)
    return "grep", "", out, 0


def view_refs(args: List[str]) -> Tuple[str, str, List[str], int]:
    # Honor the common limiting switches by selecting ref namespaces.
    prefixes: List[str] = []
    if "--branches" in args:
        prefixes.append("refs/heads")
    if "--remotes" in args:
        prefixes.append("refs/remotes")
    if "--tags" in args:
        prefixes.append("refs/tags")
    cmd = ["for-each-ref", "--format=%(refname:short)"] + prefixes
    cp = run_git(cmd)
    lines = ["  All references"]
    if cp.returncode == 0:
        lines.extend("  " + l for l in cp.stdout.splitlines() if l)
    return "refs", "All references", lines, 0


def view_stash(args: List[str]) -> Tuple[str, str, List[str], int]:
    cp = run_git(["stash", "list"] + args)
    return "stash", "", clean_lines(cp.stdout) if cp.returncode == 0 else [], 0


def view_reflog(args: List[str]) -> Tuple[str, str, List[str], int]:
    cp = run_git(["reflog", "--decorate=short"] + args)
    return "reflog", "", clean_lines(cp.stdout) if cp.returncode == 0 else [], 0


def view_status(args: List[str]) -> Tuple[str, str, List[str], int]:
    cp = run_git(["status", "--porcelain=v1", "-b"])
    lines: List[str] = []
    staged: List[str] = []
    unstaged: List[str] = []
    untracked: List[str] = []
    branch_line = ""
    if cp.returncode == 0:
        for ln in cp.stdout.splitlines():
            if ln.startswith("## "):
                branch_line = ln[3:]
                continue
            if not ln:
                continue
            code = ln[:2]
            path = ln[3:] if len(ln) > 3 else ""
            if code == "??":
                untracked.append(f"? {path}")
            else:
                if code[0] not in (" ", "?"):
                    staged.append(f"{code[0]} {path}")
                if len(code) > 1 and code[1] != " ":
                    unstaged.append(f"{code[1]} {path}")
    if branch_line.startswith("No commits yet on "):
        lines.append("Initial commit")
    elif branch_line:
        lines.append("On branch " + branch_line.split("...")[0])
    else:
        lines.append("On branch " + current_branch())
    lines.append("Changes to be committed:")
    lines.extend(("  " + x) for x in staged) if staged else lines.append("  (no files)")
    lines.append("Changes not staged for commit:")
    lines.extend(("  " + x) for x in unstaged) if unstaged else lines.append("  (no files)")
    lines.append("Untracked files:")
    lines.extend(("  " + x) for x in untracked) if untracked else lines.append("  (no files)")
    return "status", "Nothing to update", lines, 0


def view_pager(stdin_text: str) -> Tuple[str, str, List[str], int]:
    return "pager", "", clean_lines(stdin_text), 0


def build_view(argv: List[str], stdin_text: str = "") -> Tuple[str, str, List[str], int]:
    argv, _line = strip_line_number_args(argv)
    if stdin_text and not argv:
        return view_pager(stdin_text)
    if not argv:
        return view_main([])
    sub = argv[0]
    rest = argv[1:]
    if sub == "log":
        return view_log(rest)
    if sub == "show":
        return view_show(rest)
    if sub == "status":
        return view_status(rest)
    if sub == "refs":
        return view_refs(rest)
    if sub == "stash":
        return view_stash(rest)
    if sub == "reflog":
        return view_reflog(rest)
    if sub == "grep":
        return view_grep(rest)
    if sub == "blame":
        return view_blame(rest)
    return view_main(argv)


def curses_browser(stdscr, view: str, title: str, lines: List[str], start_line: int) -> None:
    curses.curs_set(0)
    try:
        curses.use_default_colors()
    except curses.error:
        pass
    # Basic color pairs resembling a blue status bar and highlighted cursor.
    try:
        curses.init_pair(1, curses.COLOR_WHITE, curses.COLOR_BLUE)
        curses.init_pair(2, curses.COLOR_WHITE, curses.COLOR_GREEN)
        curses.init_pair(3, curses.COLOR_CYAN, -1)
    except curses.error:
        pass
    pos = max(0, min(max(0, len(lines) - 1), start_line - 1))
    top = 0
    while True:
        h, w = stdscr.getmaxyx()
        body_h = max(1, h - 1)
        if pos < top:
            top = pos
        if pos >= top + body_h:
            top = pos - body_h + 1
        stdscr.erase()
        for row in range(body_h):
            idx = top + row
            if idx >= len(lines):
                break
            text = lines[idx]
            attr = curses.color_pair(2) | curses.A_BOLD if idx == pos else 0
            try:
                stdscr.addnstr(row, 0, text, max(0, w - 1), attr)
            except curses.error:
                pass
        total = len(lines)
        pct = "0%" if total == 0 else ("100%" if total <= body_h or pos >= total - 1 else f"{int((pos + 1) * 100 / total)}%")
        if title:
            status = f"[{view}] {title}"
        else:
            status = f"[{view}]"
        if total:
            status += f" - line {pos + 1} of {total}"
        status = status[:max(0, w - len(pct) - 1)]
        bar = status.ljust(max(0, w - len(pct))) + pct
        try:
            stdscr.addnstr(h - 1, 0, bar, w, curses.color_pair(1) | curses.A_BOLD)
        except curses.error:
            pass
        stdscr.refresh()
        ch = stdscr.getch()
        if ch in (ord('q'), ord('Q'), 27):
            break
        if ch in (curses.KEY_DOWN, ord('j')):
            pos = min(max(0, total - 1), pos + 1)
        elif ch in (curses.KEY_UP, ord('k')):
            pos = max(0, pos - 1)
        elif ch in (curses.KEY_NPAGE, ord(' ')):
            pos = min(max(0, total - 1), pos + body_h)
        elif ch in (curses.KEY_PPAGE, ord('b')):
            pos = max(0, pos - body_h)
        elif ch in (ord('g'), curses.KEY_HOME):
            pos = 0
        elif ch in (ord('G'), curses.KEY_END):
            pos = max(0, total - 1)
        elif ch in (ord('h'), ord('?')):
            lines[:] = [
                "Tig keybindings", "", "  q      Quit", "  j/Down Move down",
                "  k/Up   Move up", "  Space  Page down", "  b      Page up",
                "", "This is a compact reimplementation of Tig's terminal UI.",
            ]
            pos = 0; top = 0; total = len(lines)


def run_tui(view: str, title: str, lines: List[str], line: int) -> int:
    try:
        curses.wrapper(curses_browser, view, title, lines, line)
        return 0
    except curses.error:
        term = os.environ.get("TERM") or "unknown"
        sys.stdout.write(f"Error opening terminal: {term}.\n")
        return 1
    except KeyboardInterrupt:
        return 0


def main(argv: List[str]) -> int:
    try:
        argv = apply_chdir_options(argv)
    except RuntimeError as e:
        return die(str(e))

    control = first_control_option(argv)
    if control == "version":
        print_version(); return 0
    if control == "help":
        print_help(); return 0

    stripped, start_line = strip_line_number_args(argv)

    stdin_text = ""
    stdin_is_tty = sys.stdin.isatty()
    stdout_is_tty = sys.stdout.isatty()

    if not stdin_is_tty:
        # Direct non-interactive invocation in the benchmark has no /dev/tty;
        # Tig reports this before doing any pager rendering.  It still reports
        # obvious bad revisions first for a few invocation forms.
        if should_report_no_revisions(stripped):
            return die("No revisions match the given arguments.")
        return die("Failed to open tty for input")

    # From here we are terminal driven.  Validate repository for commands that
    # need Git.  `status` works in unborn repos; pager would not need a repo.
    if stripped and stripped[0] == "blame" and len(stripped) == 1:
        # Observed message includes the normal help text after the error.
        sys.stderr.write("tig: Invalid number of options to blame\n\n")
        sys.stderr.write(HELP_TEXT)
        return 1

    # Unknown first non-option behaves as a bad revision/path.
    if should_report_no_revisions(stripped):
        # The reference initializes the terminal first in a TTY; keep the final
        # message user-visible rather than attempting to mimic all escape codes.
        return die("No revisions match the given arguments.")

    # Most views require being inside a Git repository.  If Git itself is not
    # present, this is indistinguishable to users from not being in a repo.
    if not in_git_repository():
        return die("Not a git repository")

    view, title, lines, view_rc = build_view(stripped, stdin_text)
    if view == "error":
        sys.stderr.write(f"tig: {title}\n\n")
        sys.stderr.write(HELP_TEXT)
        return 1
    if not lines and (not stripped or stripped[0] not in {"log", "show", "reflog", "stash"}):
        # Empty main view in an unborn repository is a bad revision condition.
        if not stripped:
            return die("No revisions match the given arguments.")
    return run_tui(view, title, lines, start_line) if stdout_is_tty else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
